from flag_gems.runtime import torch_device_fn

"""Elementwise bitwise XOR (torch.bitwise_xor semantics) in Triton.

Public entry point: xor(A, B) -> out, computing A ^ B elementwise where each of
A / B may be an integer or bool torch.Tensor of broadcastable shape, or B may be
a Python int/bool scalar.

Strategy
--------
* bool tensors are treated as their byte storage (int8 views): bitwise XOR of
  0/1 bytes reproduces logical XOR exactly and avoids i1 codegen paths.
* For large contiguous same-shape tensors, 1-byte elements are packed 4-per-int32
  lane and 2-byte elements 2-per-int32 lane (pure bitwise op, so packing is
  exact). This raises per-lane memory width and throughput on the XPU target.
* Masks are only used when the element count is not divisible by the block size.
"""

import torch
import triton
import triton.language as tl

_BLOCKS = (
    65536,
    32768,
    16384,
    8192,
    4096,
    2048,
    1024,
    512,
    256,
    128,
    64,
    32,
    16,
    8,
    4,
    2,
    1,
)


# ---------------------------------------------------------------------------
# Kernels (all integer domain; bool handled via int8 views on the host)
# ---------------------------------------------------------------------------


@triton.jit
def _xor_nm(a_ptr, b_ptr, o_ptr, BLOCK: tl.constexpr):
    """Maskless flat xor; requires numel % BLOCK == 0."""
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    a = tl.load(a_ptr + offs)
    b = tl.load(b_ptr + offs)
    tl.store(o_ptr + offs, a ^ b)


@triton.jit
def _xor_m(a_ptr, b_ptr, o_ptr, numel, BLOCK: tl.constexpr):
    """Masked flat xor for the tail / arbitrary numel."""
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    mask = offs < numel
    a = tl.load(a_ptr + offs, mask=mask)
    b = tl.load(b_ptr + offs, mask=mask)
    tl.store(o_ptr + offs, a ^ b, mask=mask)


@triton.jit
def _xor_scalar(a_ptr, o_ptr, numel, bval, BLOCK: tl.constexpr):
    """Flat tensor ^ python-int scalar."""
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    mask = offs < numel
    a = tl.load(a_ptr + offs, mask=mask)
    tl.store(o_ptr + offs, a ^ bval, mask=mask)


@triton.jit
def _xor_bc(
    a_ptr,
    b_ptr,
    o_ptr,
    numel,
    s0,
    s1,
    s2,
    s3,
    s4,
    s5,
    s6,
    s7,
    a0,
    a1,
    a2,
    a3,
    a4,
    a5,
    a6,
    a7,
    b0,
    b1,
    b2,
    b3,
    b4,
    b5,
    b6,
    b7,
    NDIM: tl.constexpr,
    HAS_B: tl.constexpr,
    BVAL,
    BLOCK: tl.constexpr,
):
    """Generic strided/broadcast fallback. dims/strides passed innermost-first."""
    dims = [s0, s1, s2, s3, s4, s5, s6, s7]
    asa = [a0, a1, a2, a3, a4, a5, a6, a7]
    bsa = [b0, b1, b2, b3, b4, b5, b6, b7]

    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    mask = offs < numel

    rem = offs
    ia = tl.zeros([BLOCK], dtype=tl.int32)
    ib = tl.zeros([BLOCK], dtype=tl.int32)
    for j in tl.static_range(NDIM):
        coord = rem % dims[j]
        rem = rem // dims[j]
        ia += coord * asa[j]
        ib += coord * bsa[j]

    a = tl.load(a_ptr + ia, mask=mask)
    if HAS_B:
        b = tl.load(b_ptr + ib, mask=mask)
        r = a ^ b
    else:
        r = a ^ BVAL
    tl.store(o_ptr + offs, r, mask=mask)


# ---------------------------------------------------------------------------
# Host helpers
# ---------------------------------------------------------------------------

_MAX_NDIM = 8


def _broadcast_shape(shape_a, shape_b):
    sa = list(shape_a)
    sb = list(shape_b)
    if len(sa) < len(sb):
        sa = [1] * (len(sb) - len(sa)) + sa
    elif len(sb) < len(sa):
        sb = [1] * (len(sa) - len(sb)) + sb
    out = []
    for da, db in zip(sa, sb):
        if da == db:
            out.append(da)
        elif da == 1:
            out.append(db)
        elif db == 1:
            out.append(da)
        else:
            raise ValueError(
                f"operands could not be broadcast together with shapes "
                f"{tuple(shape_a)} {tuple(shape_b)}"
            )
    return tuple(out)


def _to_int_view(t):
    """bool tensors are handled in their int8 byte domain."""
    if t.dtype == torch.bool:
        return t.view(torch.int8)
    return t


def _pick_block(lanes):
    for b in _BLOCKS:
        if lanes >= b and lanes % b == 0:
            return b
    return 1


def _packed_lane_dtype(dtype):
    """(pk_dtype, pack) if byte-storage packing applies, else None."""
    if dtype in (torch.bool, torch.int8, torch.uint8):
        return torch.int32, 4
    if dtype == torch.int16:
        return torch.int32, 2
    return None


def _flat_equal(a, b, out, numel, a_dtype):
    """Launch over equal-size, contiguous, flat tensor-tensor inputs."""
    # optional multi-byte packing
    pack_info = _packed_lane_dtype(a_dtype)
    if pack_info is not None and numel % pack_info[1] == 0:
        pk, pack = pack_info
        if a.data_ptr() % 4 == 0 and b.data_ptr() % 4 == 0 and out.data_ptr() % 4 == 0:
            af = a.reshape(-1)
            of = out.reshape(-1)
            bf = b.reshape(-1)
            lanes = numel // pack
            ap = af.view(pk)
            op = of.view(pk)
            bp = bf.view(pk)
            block = _pick_block(lanes)
            if lanes % block == 0:
                _xor_nm[(lanes // block,)](ap, bp, op, BLOCK=block)
            else:
                _xor_m[(triton.cdiv(lanes, block),)](ap, bp, op, lanes, BLOCK=block)
            return
    # native element domain
    lanes = numel
    block = _pick_block(lanes)
    if lanes % block == 0:
        _xor_nm[(lanes // block,)](a, b, out, BLOCK=block)
    else:
        _xor_m[(triton.cdiv(lanes, block),)](a, b, out, lanes, BLOCK=block)


def _launch_bc(a, b, out, shape_a, shape_b, bval, has_b):
    ndim_out = max(len(out.shape), 1)
    padded_a = _aligned(shape_a, ndim_out)
    padded_b = _aligned(shape_b, ndim_out)
    sa = _bcast_strides(a, padded_a, ndim_out)
    sb = _bcast_strides(b, padded_b, ndim_out)
    sd = [max(padded_a[d], padded_b[d]) for d in range(ndim_out)]
    # innermost-first ordering for the coordinate decode
    sd = list(reversed(sd))
    sa = list(reversed(sa))
    sb = list(reversed(sb))
    args = [sd[d] if d < ndim_out else 1 for d in range(_MAX_NDIM)]
    aa = [sa[d] if d < ndim_out else 0 for d in range(_MAX_NDIM)]
    bb = [sb[d] if d < ndim_out else 0 for d in range(_MAX_NDIM)]
    numel = out.numel()
    if numel == 0:
        return
    block = 256 if numel > 256 else max(numel, 1)
    if block < 1:
        return
    _xor_bc[(triton.cdiv(numel, block),)](
        a,
        b,
        out,
        numel,
        *args,
        *aa,
        *bb,
        NDIM=ndim_out,
        HAS_B=has_b,
        BVAL=bval,
        BLOCK=block,
    )


def _aligned(shape, ndim_out):
    if len(shape) < ndim_out:
        shape = (1,) * (ndim_out - len(shape)) + tuple(shape)
    return shape


def _bcast_strides(t, padded_shape, ndim_out):
    base = 0 if t.ndim == 0 else (ndim_out - t.ndim)
    st = []
    for d in range(ndim_out):
        if d < base:
            st.append(0)
        else:
            st.append(0 if padded_shape[d] == 1 else t.stride(d - base))
    return st


