# Public entry point
# ---------------------------------------------------------------------------


def xor(A, B):
    with torch_device_fn.device(A.device):
        """out = A ^ B elementwise (torch.bitwise_xor semantics)."""
        if isinstance(B, torch.Tensor):
            if (
                A.dtype == B.dtype
                and A.shape == B.shape
                and A.is_contiguous()
                and B.is_contiguous()
            ):
                numel = A.numel()
                out = torch.empty(A.shape, dtype=A.dtype, device=A.device)
                if numel > 0:
                    _flat_equal(
                        _to_int_view(A),
                        _to_int_view(B),
                        _to_int_view(out),
                        numel,
                        A.dtype,
                    )
                return out
            out_shape = _broadcast_shape(tuple(A.shape), tuple(B.shape))
            out_dtype = torch.promote_types(A.dtype, B.dtype)
            out = torch.empty(out_shape, dtype=out_dtype, device=A.device)
            _launch_bc(
                _to_int_view(A),
                _to_int_view(B),
                _to_int_view(out),
                tuple(A.shape),
                tuple(B.shape),
                0,
                True,
            )
            return out

        # Python int / bool scalar B
        out = torch.empty(A.shape, dtype=A.dtype, device=A.device)
        bval = int(B)
        numel = A.numel()
        av = _to_int_view(A)
        ov = _to_int_view(out)
        if numel > 0 and A.is_contiguous():
            block = 1024
            _xor_scalar[(triton.cdiv(numel, block),)](av, ov, numel, bval, BLOCK=block)
        else:
            _launch_bc(av, ov, ov, tuple(A.shape), (1,) * A.ndim, bval, False)
        return out


xor_scalar = xor
